"use client";

import SettingsHub from "@/components/settings/SettingsHub";

/**
 * /settings entry point — hub page showing every settings category as
 * a card. Clicking a card navigates to /settings/<key> which renders
 * the dedicated detail page (see app/(app)/settings/[key]/page.tsx).
 */
const Settings = () => <SettingsHub />;

export default Settings;

"use client";

import Link from "next/link";
import { ChevronRight } from "lucide-react";
import {
  SETTINGS_ENTRIES,
  SETTINGS_GROUPS,
  type SettingsEntry,
} from "@/components/settings/settings-config";
import { cn } from "@/lib/utils";

/**
 * Hub page at /settings. Shows every settings category as a card
 * grouped by {Personal, Organization, Advanced}. Clicking a card
 * navigates to /settings/<key>.
 *
 * Grid: 1 col mobile → 2 col tablet → 3 col desktop.
 * Cards use next/link with prefetch so navigating feels instant.
 */
const SettingsHub = () => {
  return (
    <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
      <header className="mb-8">
        <h1 className="text-2xl font-bold text-foreground">Settings</h1>
        <p className="text-sm text-muted-foreground mt-1">
          Configure your account and workspace.
        </p>
      </header>

      <div className="space-y-10">
        {SETTINGS_GROUPS.map((group) => {
          const entries = SETTINGS_ENTRIES.filter((e) => e.group === group.key);
          if (entries.length === 0) return null;
          return (
            <section key={group.key} aria-labelledby={`settings-group-${group.key}`}>
              <div className="mb-3">
                <h2
                  id={`settings-group-${group.key}`}
                  className="text-[10.5px] font-semibold uppercase tracking-[0.12em] text-muted-foreground/70"
                >
                  {group.label}
                </h2>
                <p className="text-xs text-muted-foreground/80 mt-0.5">
                  {group.description}
                </p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {entries.map((entry) => (
                  <SettingsCard key={entry.key} entry={entry} />
                ))}
              </div>
            </section>
          );
        })}
      </div>
    </main>
  );
};

const SettingsCard = ({ entry }: { entry: SettingsEntry }) => {
  const Icon = entry.icon;
  return (
    <Link
      href={`/settings/${entry.key}`}
      prefetch
      className={cn(
        "group relative flex items-start gap-4 rounded-xl border border-border/60 bg-card p-4",
        "transition-all duration-150",
        "hover:border-primary/40 hover:shadow-md hover:-translate-y-0.5",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40",
      )}
    >
      <div
        className={cn(
          "shrink-0 h-10 w-10 rounded-lg flex items-center justify-center",
          "bg-primary/10 text-primary transition-colors",
          "group-hover:bg-primary/15",
        )}
      >
        <Icon className="h-5 w-5" />
      </div>

      <div className="flex-1 min-w-0">
        <h3 className="text-sm font-semibold text-foreground leading-tight">
          {entry.label}
        </h3>
        <p className="text-xs text-muted-foreground mt-1 leading-relaxed line-clamp-2">
          {entry.description}
        </p>
      </div>

      <ChevronRight
        className={cn(
          "shrink-0 h-4 w-4 text-muted-foreground/40 mt-1",
          "transition-all duration-150",
          "group-hover:text-primary group-hover:translate-x-0.5",
        )}
      />
    </Link>
  );
};

export default SettingsHub;

import {
  UserCircle,
  Building2,
  CreditCard,
  Globe,
  Plug,
  Users,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

// `agency` is NOT a settings category — Agency Hub lives in the
// workspace switcher at the top of the sidebar (see AgencySidebar +
// useWorkspace) and owns its own top-level /agency route.
export type SettingsKey =
  | "account"
  | "workspace"
  | "team"
  | "billing"
  | "career"
  | "integrations";

export type SettingsGroup = "personal" | "organization" | "advanced";

export type SettingsEntry = {
  key: SettingsKey;
  label: string;
  description: string;
  icon: LucideIcon;
  group: SettingsGroup;
};

/**
 * Single source of truth for the Settings catalog. Used by both the
 * hub page (cards grid) and the individual detail pages (title + icon
 * + breadcrumb). Adding a new category = append one row here + create
 * the tab component under settings/tabs/.
 */
export const SETTINGS_ENTRIES: SettingsEntry[] = [
  {
    key: "account",
    label: "Account",
    description: "Profile, password, and personal preferences.",
    icon: UserCircle,
    group: "personal",
  },
  {
    key: "workspace",
    label: "Workspace",
    description: "Workspace-wide automation and defaults.",
    icon: Building2,
    group: "organization",
  },
  {
    key: "team",
    label: "Team members",
    description: "Invite teammates and manage their roles.",
    icon: Users,
    group: "organization",
  },
  {
    key: "billing",
    label: "Billing & plan",
    description: "Subscription, credits, and payment history.",
    icon: CreditCard,
    group: "advanced",
  },
  {
    key: "career",
    label: "Career page",
    description: "Public careers page, branding, and subscribers.",
    icon: Globe,
    group: "advanced",
  },
  {
    key: "integrations",
    label: "Integrations",
    description: "Slack, webhooks, email, and API connections.",
    icon: Plug,
    group: "advanced",
  },
];

export const SETTINGS_GROUPS: Array<{
  key: SettingsGroup;
  label: string;
  description: string;
}> = [
  {
    key: "personal",
    label: "Personal",
    description: "Just for you — nobody else on the workspace sees these.",
  },
  {
    key: "organization",
    label: "Organization",
    description: "Shared configuration for everyone in this workspace.",
  },
  {
    key: "advanced",
    label: "Advanced",
    description: "Billing, public-facing surfaces, and third-party tools.",
  },
];

export function getSettingsEntry(key: string): SettingsEntry | null {
  return SETTINGS_ENTRIES.find((e) => e.key === key) ?? null;
}

"use client";

import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useTeam } from "@/hooks/useTeam";
import { supabase } from "@/integrations/supabase/client";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { LogOut, Zap, MessageCircle } from "lucide-react";
import { toast } from "sonner";
import AvailabilitySettings from "@/components/AvailabilitySettings";

/**
 * Personal account: profile toggles, WhatsApp, availability, sign out.
 * Moved verbatim from the old Settings.tsx page so existing behavior is
 * preserved 1:1. Workspace-wide settings live in the Workspace tab.
 */
const AccountTab = () => {
  const { user, profile, signOut, refreshProfile } = useAuth();
  const { team } = useTeam();
  const autoRank = profile?.auto_rank_enabled ?? true;
  const [whatsappNumber, setWhatsappNumber] = useState<string>(
    (profile as { whatsapp_number?: string } | null)?.whatsapp_number ?? "",
  );
  const [savingWhatsapp, setSavingWhatsapp] = useState(false);

  const toggleAutoRank = async (enabled: boolean) => {
    if (!user) return;
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ auto_rank_enabled: enabled } as never)
        .eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      toast.success(enabled ? "Auto-rank enabled" : "Auto-rank disabled");
    } catch {
      toast.error("Failed to update setting");
    }
  };

  const saveWhatsappNumber = async () => {
    if (!user) return;
    setSavingWhatsapp(true);
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ whatsapp_number: whatsappNumber.trim() || null } as never)
        .eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      toast.success("WhatsApp number saved");
    } catch {
      toast.error("Failed to save WhatsApp number");
    } finally {
      setSavingWhatsapp(false);
    }
  };

  return (
    <div className="px-6 sm:px-8 lg:px-10 py-8 space-y-6">
      {/* Auto-rank toggle */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Zap className="h-5 w-5 text-primary" />
              <CardTitle className="text-sm font-semibold">
                Auto-rank resumes
              </CardTitle>
            </div>
            <Switch checked={autoRank} onCheckedChange={toggleAutoRank} />
          </div>
          <CardDescription>
            {autoRank
              ? "Resumes are automatically scored after upload. Credits are used immediately."
              : "Resumes stay as Pending after upload. You choose when to rank and spend credits."}
          </CardDescription>
        </CardHeader>
      </Card>

      {/* WhatsApp number */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <MessageCircle className="h-5 w-5 text-[#25D366]" />
            <CardTitle className="text-sm font-semibold">
              WhatsApp Number
            </CardTitle>
          </div>
          <CardDescription>
            Your WhatsApp number is pre-filled when messaging candidates.
            Include country code (e.g. +1 555 123 4567).
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2">
            <div className="flex-1">
              <Label htmlFor="whatsapp-number" className="sr-only">
                WhatsApp Number
              </Label>
              <Input
                id="whatsapp-number"
                value={whatsappNumber}
                onChange={(e) => setWhatsappNumber(e.target.value)}
                placeholder="+1 555 123 4567"
                type="tel"
              />
            </div>
            <Button
              size="sm"
              onClick={saveWhatsappNumber}
              disabled={savingWhatsapp}
              className="shrink-0"
            >
              {savingWhatsapp ? "Saving..." : "Save"}
            </Button>
          </div>
        </CardContent>
      </Card>

      {user && <AvailabilitySettings userId={user.id} teamId={team?.id} />}

      <Card className="border border-border/60 shadow-sm">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-sm font-semibold">
            <LogOut className="h-5 w-5" />
            Account
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Button variant="outline" onClick={signOut}>
            Sign out
          </Button>
        </CardContent>
      </Card>
    </div>
  );
};

export default AccountTab;

"use client";

import { useEffect, useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { useTeam } from "@/hooks/useTeam";
import { supabase } from "@/integrations/supabase/client";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Building2, Mail, Save, Coins } from "lucide-react";
import { toast } from "sonner";
import { FX_CURRENCIES, type FxCurrencyCode } from "@/lib/fx";

type PlatformConfigRow = {
  max_resumes_per_job?: number | null;
  max_file_size_mb?: number | null;
  email_ingestion_enabled?: boolean | null;
};

type AccountCurrencyRow = { preferred_currency?: string | null };

const WorkspaceTab = () => {
  const { user } = useAuth();
  const { team } = useTeam();
  const qc = useQueryClient();
  const [workspaceName, setWorkspaceName] = useState(team?.name ?? "");
  const [savingName, setSavingName] = useState(false);

  const [maxResumes, setMaxResumes] = useState<string>("");
  const [maxFileMb, setMaxFileMb] = useState<string>("");
  const [emailIngest, setEmailIngest] = useState<boolean>(false);
  const [savingConfig, setSavingConfig] = useState(false);

  const [currency, setCurrency] = useState<FxCurrencyCode>("USD");
  const [savingCurrency, setSavingCurrency] = useState(false);

  useEffect(() => {
    if (team?.name) setWorkspaceName(team.name);
  }, [team?.name]);

  useEffect(() => {
    const load = async () => {
      const { data } = await supabase
        .from("platform_config")
        .select("max_resumes_per_job, max_file_size_mb, email_ingestion_enabled")
        .limit(1)
        .maybeSingle();
      const row = data as PlatformConfigRow | null;
      if (row) {
        setMaxResumes(String(row.max_resumes_per_job ?? 1000));
        setMaxFileMb(String(row.max_file_size_mb ?? 10));
        setEmailIngest(row.email_ingestion_enabled ?? false);
      }
    };
    if (user) void load();
  }, [user]);

  useEffect(() => {
    const load = async () => {
      if (!team?.id) return;
      const { data } = await (supabase as unknown as {
        from: (t: string) => {
          select: (s: string) => {
            eq: (c: string, v: string) => {
              maybeSingle: () => Promise<{
                data: AccountCurrencyRow | null;
              }>;
            };
          };
        };
      })
        .from("accounts")
        .select("preferred_currency")
        .eq("id", team.id)
        .maybeSingle();
      const code = (data?.preferred_currency ?? "USD").toUpperCase();
      if (FX_CURRENCIES.some((c) => c.code === code)) {
        setCurrency(code as FxCurrencyCode);
      }
    };
    void load();
  }, [team?.id]);

  const saveWorkspaceName = async () => {
    if (!team?.id) return;
    setSavingName(true);
    try {
      const { error } = await supabase
        .from("teams")
        .update({ name: workspaceName.trim() } as never)
        .eq("id", team.id);
      if (error) throw error;
      toast.success("Workspace name updated");
    } catch {
      toast.error("Failed to update workspace name");
    } finally {
      setSavingName(false);
    }
  };

  const saveCurrency = async () => {
    if (!team?.id) return;
    setSavingCurrency(true);
    try {
      const { error } = await (supabase as unknown as {
        from: (t: string) => {
          update: (p: Record<string, unknown>) => {
            eq: (c: string, v: string) => Promise<{ error: unknown }>;
          };
        };
      })
        .from("accounts")
        .update({ preferred_currency: currency })
        .eq("id", team.id);
      if (error) throw error;
      // Invalidate any cached workspace currency + rates so every <Price>
      // in the app re-renders in the new currency immediately.
      qc.invalidateQueries({ queryKey: ["account-currency", team.id] });
      qc.invalidateQueries({ queryKey: ["currency-rates"] });
      toast.success(`Currency set to ${currency}`);
    } catch {
      toast.error("Failed to update currency");
    } finally {
      setSavingCurrency(false);
    }
  };

  const saveConfig = async () => {
    setSavingConfig(true);
    try {
      const payload = {
        max_resumes_per_job: Number(maxResumes) || 1000,
        max_file_size_mb: Number(maxFileMb) || 10,
        email_ingestion_enabled: emailIngest,
      };
      // platform_config view is already filtered per-account via its WHERE
      // clause (migration 0019) so any row we can update is ours. Filter on
      // account_id for a concrete predicate (view exposes it as a real
      // column, "id" is only an alias and isn't in the generated types).
      const { error } = await supabase
        .from("platform_config")
        .update(payload as never)
        .eq("account_id", (team?.id ?? "") as never);
      if (error) throw error;
      toast.success("Workspace defaults saved");
    } catch {
      toast.error("Failed to save workspace defaults");
    } finally {
      setSavingConfig(false);
    }
  };

  return (
    <div className="px-6 sm:px-8 lg:px-10 py-8 space-y-6">
      <Card className="border border-border/60 shadow-sm">
        <CardHeader>
          <div className="flex items-center gap-2">
            <Building2 className="h-5 w-5 text-primary" />
            <CardTitle className="text-sm font-semibold">
              Workspace name
            </CardTitle>
          </div>
          <CardDescription>
            Shown on invites, email notifications, and the public career page.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2">
            <div className="flex-1">
              <Label htmlFor="workspace-name" className="sr-only">
                Workspace name
              </Label>
              <Input
                id="workspace-name"
                value={workspaceName}
                onChange={(e) => setWorkspaceName(e.target.value)}
                placeholder="Acme Inc."
              />
            </div>
            <Button
              size="sm"
              onClick={saveWorkspaceName}
              disabled={savingName || !workspaceName.trim()}
              className="shrink-0"
            >
              <Save className="h-4 w-4 mr-1" />
              {savingName ? "Saving…" : "Save"}
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card className="border border-border/60 shadow-sm">
        <CardHeader>
          <div className="flex items-center gap-2">
            <Coins className="h-5 w-5 text-primary" />
            <CardTitle className="text-sm font-semibold">
              Preferred currency
            </CardTitle>
          </div>
          <CardDescription>
            Applies to billing, credit packs, agency invoicing, and
            revenue widgets. Rates refresh daily from a live FX feed.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2">
            <div className="flex-1">
              <Label htmlFor="preferred-currency" className="sr-only">
                Preferred currency
              </Label>
              <Select
                value={currency}
                onValueChange={(v) => setCurrency(v as FxCurrencyCode)}
              >
                <SelectTrigger id="preferred-currency">
                  <SelectValue placeholder="Select a currency" />
                </SelectTrigger>
                <SelectContent>
                  {FX_CURRENCIES.map((c) => (
                    <SelectItem key={c.code} value={c.code}>
                      <span className="inline-flex items-center gap-2">
                        <span className="font-mono text-xs text-muted-foreground w-6 shrink-0">
                          {c.symbol}
                        </span>
                        <span className="font-semibold">{c.code}</span>
                        <span className="text-muted-foreground">
                          · {c.name}
                        </span>
                      </span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <Button
              size="sm"
              onClick={saveCurrency}
              disabled={savingCurrency}
              className="shrink-0"
            >
              <Save className="h-4 w-4 mr-1" />
              {savingCurrency ? "Saving…" : "Save"}
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card className="border border-border/60 shadow-sm">
        <CardHeader>
          <CardTitle className="text-sm font-semibold">
            Resume processing defaults
          </CardTitle>
          <CardDescription>
            Apply across every job in this workspace.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="max-resumes" className="text-xs font-medium">
                Max resumes per job
              </Label>
              <Input
                id="max-resumes"
                type="number"
                min={1}
                max={10000}
                value={maxResumes}
                onChange={(e) => setMaxResumes(e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="max-file-mb" className="text-xs font-medium">
                Max file size (MB)
              </Label>
              <Input
                id="max-file-mb"
                type="number"
                min={1}
                max={50}
                value={maxFileMb}
                onChange={(e) => setMaxFileMb(e.target.value)}
                className="mt-1"
              />
            </div>
          </div>
          <div className="flex items-start justify-between gap-4 pt-2 border-t">
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <Mail className="h-4 w-4 text-muted-foreground" />
                <Label
                  htmlFor="email-ingest"
                  className="text-sm font-semibold"
                >
                  Email ingest
                </Label>
              </div>
              <p className="text-xs text-muted-foreground mt-1">
                Forward resumes to your inbox address and we'll parse and
                rank them automatically.
              </p>
            </div>
            <Switch
              id="email-ingest"
              checked={emailIngest}
              onCheckedChange={setEmailIngest}
            />
          </div>
          <div className="flex justify-end pt-2">
            <Button size="sm" onClick={saveConfig} disabled={savingConfig}>
              <Save className="h-4 w-4 mr-1" />
              {savingConfig ? "Saving…" : "Save defaults"}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default WorkspaceTab;

