import { notFound } from "next/navigation";
import SettingsDetailShell from "@/components/settings/SettingsDetailShell";
import {
  SETTINGS_ENTRIES,
  getSettingsEntry,
  type SettingsKey,
} from "@/components/settings/settings-config";

import AccountTab from "@/components/settings/tabs/AccountTab";
import WorkspaceTab from "@/components/settings/tabs/WorkspaceTab";
import TeamTab from "@/components/settings/tabs/TeamTab";
import BillingTab from "@/components/settings/tabs/BillingTab";
import CareerPageTab from "@/components/settings/tabs/CareerPageTab";
import IntegrationsTab from "@/components/settings/tabs/IntegrationsTab";

/**
 * Dynamic settings detail route: /settings/{key}. Renders the matching
 * tab body wrapped in SettingsDetailShell (breadcrumb + title).
 * Invalid keys → 404.
 *
 * Static params are pre-generated for all valid keys so Next can
 * prerender shells and hydrate fast; the inner content is still
 * client-rendered by the tab components (they hit Supabase at runtime).
 */

const TAB_COMPONENTS: Record<string, React.ComponentType> = {
  account: AccountTab,
  workspace: WorkspaceTab,
  team: TeamTab,
  billing: BillingTab,
  career: CareerPageTab,
  integrations: IntegrationsTab,
};

export function generateStaticParams() {
  return SETTINGS_ENTRIES.map((e) => ({ key: e.key }));
}

export default async function SettingsDetailPage({
  params,
}: {
  params: Promise<{ key: string }>;
}) {
  const { key } = await params;
  const entry = getSettingsEntry(key);
  const TabBody = TAB_COMPONENTS[key];
  if (!entry || !TabBody) notFound();

  // Pass the key (plain string) — SettingsDetailShell is a Client
  // Component and can't receive the Lucide icon component in `entry`
  // across the Server→Client boundary.
  return (
    <SettingsDetailShell entryKey={entry.key as SettingsKey}>
      <TabBody />
    </SettingsDetailShell>
  );
}

