/**
 * Wraps a settings detail page (rendered by `app/(app)/settings/[key]/page.tsx`)
 * with a sticky breadcrumb header, back link, category title, and
 * description. The body slot receives the tab content component.
 *
 * Accepts just the entry `key` (plain string) — never the full
 * `entry` object — because the entry carries a Lucide icon component
 * which can't cross the Server→Client boundary. The shell looks up
 * the rest of the metadata client-side via getSettingsEntry.
 */
const SettingsDetailShell = ({
  entryKey,
  children,
}: {
  entryKey: SettingsKey;
  children: React.ReactNode;
}) => {
  const entry = getSettingsEntry(entryKey);
  if (!entry) return null;
  const Icon = entry.icon;
  return (
    <div className="flex flex-col h-full w-full">
      <header className="border-b bg-background sticky top-0 z-10">
        <div className="px-6 sm:px-8 lg:px-10 pt-5 pb-4">
          <Link
            href="/settings"
            prefetch
            className="inline-flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
          >
            <ArrowLeft className="h-3.5 w-3.5" />
            Settings
          </Link>
          <div className="mt-3 flex items-start gap-3">
            <div className="shrink-0 h-10 w-10 rounded-lg bg-primary/10 text-primary flex items-center justify-center">
              <Icon className="h-5 w-5" />
            </div>
            <div className="flex-1 min-w-0">
              <h1 className="text-xl font-bold text-foreground leading-tight">
                {entry.label}
              </h1>
              <p className="text-sm text-muted-foreground mt-0.5">
                {entry.description}
              </p>
            </div>
          </div>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto">
        {/*
          Child tab components own their own padding (`px-6 sm:px-8
          lg:px-10 py-8`) so they fit naturally here without extra
          wrapper spacing.
        */}
        {children}
      </div>
    </div>
  );
};

